#include <control/reconciliation/native_reconciler.hpp>
namespace rebuntu::reconciliation { std::vector<Drift> Reconciler::diff(const DesiredState&d,const model::StateStore&s)const{std::vector<Drift>o;for(auto&[k,v]:d.properties){auto f=s.get(d.subject,k);auto observed=f?f->value:"<unknown>";if(observed!=v)o.push_back({k,observed,v});}return o;} std::vector<platform::v0040::ChangePlan> Reconciler::plans(const DesiredState&d,const model::StateStore&s,const planning::ChangePlanner&p)const{std::vector<platform::v0040::ChangePlan>o;for(auto&x:diff(d,s))o.push_back(p.plan({"configuration",d.subject,x.property,x.desired,true,false}));return o;} }
